'use strict';

/**
 * Bundles the edge worker into one self-contained file.
 *
 * That single file can be pasted straight into the Cloudflare dashboard editor,
 * so publishing needs no command line at all.
 */

const path = require('path');
const fs = require('fs');
const esbuild = require('esbuild');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'worker', 'dist', 'worker.js');

esbuild
  .build({
    entryPoints: [path.join(ROOT, 'worker', 'src', 'index.js')],
    bundle: true,
    format: 'esm',
    target: 'es2022',
    platform: 'neutral',
    outfile: OUT,
    banner: {
      js: '// PulseDesk edge worker — generated by tools/bundle-worker.js. Created by Dheerav Tandon.\n' +
          '// Paste this whole file into the Cloudflare dashboard worker editor, or deploy with wrangler.\n'
    },
    legalComments: 'none'
  })
  .then(() => {
    const kb = (fs.statSync(OUT).size / 1024).toFixed(1);
    console.log(`worker bundle → ${OUT} (${kb} KB)`);
    console.log('Paste it into: Cloudflare dashboard → Workers & Pages → your worker → Edit code');
  })
  .catch((err) => {
    console.error(err.message);
    process.exit(1);
  });
